1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () =>
55	        answerInTurn(ws, session, orchestrator, sessionStore, validation, signal)
56	      );
57	    }
58	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
59	    return wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore));
60	  };
61	}
62	
63	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
64	async function answerInTurn(
65	  ws: WebSocket,
66	  session: ChatSession,
67	  orchestrator: ChatOrchestrator,
68	  sessionStore: SessionStore | undefined,
69	  validation: ValidationResult,
70	  signal: AbortSignal | undefined
71	): Promise<void> {
72	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
73	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
74	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
75	    return;
76	  }
77	  const startedAt = Date.now();
78	  try {
79	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, sessionStore, validation, signal));
80	  } finally {
81	    endTurn(ws, session, signal, startedAt);
82	  }
83	}
84	
85	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
86	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
87	  if (signal?.aborted) {
88	    log.info('message', 'turn abandoned: its socket closed', {
89	      sessionId: session.sessionId,
90	      elapsedMs: Date.now() - startedAt,
91	    });
92	    return;
93	  }
94	  sendStreamEnd(ws);
95	}
96	
97	async function answerUserMessage(
98	  ws: WebSocket,
99	  session: ChatSession,
100	  orchestrator: ChatOrchestrator,
101	  sessionStore: SessionStore | undefined,
102	  validation: ValidationResult,
103	  signal: AbortSignal | undefined
104	): Promise<void> {
105	  const message = validation.valid ? validation.data : undefined;
106	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
107	  await answerFrame(ws, session, validation, sessionStore);
108	}
109	
110	async function answerFrame(
111	  ws: WebSocket,
112	  session: ChatSession,
113	  validation: ValidationResult,
114	  sessionStore: SessionStore | undefined
115	): Promise<void> {
116	  if (!validation.valid) {
117	    log.warn('message', 'validation failed', {error: validation.error});
118	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
119	    return;
120	  }
121	
122	  const message = validation.data;
123	  if (message.type === 'ping') handlePing(ws, message.timestamp);
124	  if (message.type === 'list_sessions') await answerListSessions(ws, session, sessionStore, message);
125	}
126	
127	// Off the lock, beside ping: a history request is not a turn and mutates nothing.
128	async function answerListSessions(
129	  ws: WebSocket,
130	  session: ChatSession,
131	  sessionStore: SessionStore | undefined,
132	  message: ListSessionsMessage
133	): Promise<void> {
134	  let listed: SessionSummary[] | undefined;
135	  try {
136	    // The user is the session's, read here and never from the frame the validator already stripped.
137	    listed = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
138	  } catch (error) {
139	    log.error('ws', 'listing sessions failed', {
140	      sessionId: session.sessionId,
141	      userId: session.userId,
142	      error: messageOf(error),
143	    });
144	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
145	    return;
146	  }
147	  sendSessionList(ws, listed ?? []);
148	}
149	
150	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
151	function isUserMessageFrame(rawMessage: unknown): boolean {
152	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
153	}
154	
155	function messageOf(error: unknown): string {
156	  return error instanceof Error ? error.message : 'Unknown error';
157	}
158	
159	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
160	  try {
161	    await action();
162	  } catch (error) {
163	    const message = messageOf(error);
164	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
165	    log.error('message', 'handling error', {error: message, code});
166	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
167	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
168	      return;
169	    }
170	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
171	  }
172	}
173	
174	async function handleUserMessage(
175	  ws: WebSocket,
176	  session: ChatSession,
177	  orchestrator: ChatOrchestrator,
178	  content: string,
179	  signal: AbortSignal | undefined
180	): Promise<void> {
181	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
182	
183	  const userEntry = createUserEntry(content);
184	  const userIndex = appendEntry(session, userEntry);
185	  sendUpsert(ws, userIndex, userEntry);
186	
187	  const parser = new ThinkingTagParser();
188	  const state: StreamState = {
189	    thinkingIndex: null,
190	    assistantIndex: null,
191	    suppressOutput: false,
192	    sentAssistantIndices: [],
193	  };
194	
195	  let textChunkCount = 0;
196	
197	  try {
198	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
199	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
200	      if (signal?.aborted) break;
201	      textChunkCount = logChunk(chunk, textChunkCount);
202	      processChunk(ws, session, state, parser, chunk);
203	    }
204	  } finally {
205	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
206	    flushHeldText(ws, session, state, parser);
207	    closeCutOff(ws, session, state, 'thinkingIndex');
208	    closeCutOff(ws, session, state, 'assistantIndex');
209	  }
210	
211	  if (textChunkCount > 0) {
212	    log.debug('stream', `received ${textChunkCount} text chunks`);
213	  }
214	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
215	}
216	
217	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
218	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
219	  if (chunk.type === 'text') return textChunkCount + 1;
220	
221	  if (textChunkCount > 0) {
222	    log.debug('stream', `received ${textChunkCount} text chunks`);
223	  }
224	
225	  if (chunk.type === 'tool_result') {
226	    log.debug('stream', 'tool_result chunk', {
227	      messageCount: chunk.clientMessages.length,
228	      types: chunk.clientMessages.map(m => m.type),
229	    });
230	    return 0;
231	  }
232	
233	  log.debug('stream', 'chunk', {type: chunk.type});
234	  return 0;
235	}
236	
237	function processChunk(
238	  ws: WebSocket,
239	  session: ChatSession,
240	  state: StreamState,
241	  parser: ThinkingTagParser,
242	  chunk: MessageChunk
243	): void {
244	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
245	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
246	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
247	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
248	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
249	}
250	
251	function processTextChunk(
252	  ws: WebSocket,
253	  session: ChatSession,
254	  state: StreamState,
255	  parser: ThinkingTagParser,
256	  text: string
257	): void {
258	  const segments = parser.push(text);
259	  for (const segment of segments) {
260	    handleTextSegment(ws, session, state, segment);
261	  }
262	}
263	
264	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
265	  if (segment.type === 'thinking') {
266	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
267	    return;
268	  }
269	  commitAndClear(ws, session, state, 'thinkingIndex');
270	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
271	}
272	
273	function streamSegment(
274	  ws: WebSocket,
275	  session: ChatSession,
276	  state: StreamState,
277	  key: StateIndexKey,
278	  createEntry: EntryFactory,
279	  content: string
280	): void {
281	  const isNew = initSegment(session, state, key, createEntry);
282	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
283	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
284	  appendDelta(session, state[key]!, content);
285	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
286	}
287	
288	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
289	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
290	  markSuppressed(session, index);
291	  sendSkip(ws, index);
292	}
293	
294	function markSuppressed(session: ChatSession, index: number): void {
295	  const entry = session.entries[index];
296	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
297	}
298	
299	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
300	  if (state[key] !== null) return false;
301	  state[key] = appendEntry(session, createEntry());
302	  return true;
303	}
304	
305	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
306	  const index = state[key];
307	  if (index === null) return;
308	
309	  commitEntry(session, index);
310	  state[key] = null;
311	
312	  // Only what the client received can be retracted, and only assistant entries.
313	  if (state.suppressOutput) return;
314	
315	  sendCommit(ws, index);
316	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
317	}
318	
319	function processToolUseChunk(
320	  ws: WebSocket,
321	  session: ChatSession,
322	  toolCall: {name: string; input: Record<string, unknown>}
323	): void {
324	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
325	  const toolIndex = appendEntry(session, toolEntry);
326	  sendUpsert(ws, toolIndex, toolEntry);
327	}
328	
329	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
330	  for (const msg of clientMessages) {
331	    log.debug('stream', 'forwarding client message to frontend', {
332	      type: msg.type,
333	      index: 'index' in msg ? msg.index : undefined,
334	    });
335	    sendJson(ws, msg);
336	  }
337	}
338	
339	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
340	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
341	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
342	  commitOpenEntries(ws, session, state);
343	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
344	
345	  for (const idx of state.sentAssistantIndices) {
346	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
347	    markSuppressed(session, idx);
348	  }
349	
350	  state.sentAssistantIndices = [];
351	  state.suppressOutput = true;
352	}
353	
354	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
355	  flushHeldText(ws, session, state, parser);
356	  commitOpenEntries(ws, session, state);
357	}
358	
359	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
360	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
361	  for (const segment of parser.flush()) {
362	    handleTextSegment(ws, session, state, segment);
363	  }
364	}
365	
366	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
367	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
368	  const index = state[key];
369	  if (index === null) return;
370	  markTruncated(session, index);
371	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
372	  commitAndClear(ws, session, state, key);
373	}
374	
375	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
376	  commitAndClear(ws, session, state, 'thinkingIndex');
377	  commitAndClear(ws, session, state, 'assistantIndex');
378	}
379	
380	function handlePing(ws: WebSocket, timestamp: number): void {
381	  ws.send(JSON.stringify({type: 'pong', timestamp}));
382	}
