// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

describe('a conversation list', () => {
  it('answers list_sessions for the user on the session, forwarding limit and before with dates serialised and a frame userId ignored', async () => {
    const before = {updatedAt: '2026-02-02T00:00:00.000Z', sessionId: 's8'};
    const asked: Array<{userId: string | number; options: unknown}> = [];
    const listed = [
      {
        sessionId: 's9',
        createdAt: new Date('2026-02-02T00:00:00.000Z'),
        updatedAt: new Date('2026-02-02T00:01:00.000Z'),
        entryCount: 2,
      },
    ];
    const store = {
      listFor: (userId: string | number, options?: unknown) => {
        asked.push({userId, options});
        return listed;
      },
    } as unknown as SessionStore;

    const h = harness([], {}, store);
    await h.send({type: 'list_sessions', limit: 3, before, userId: 'someone-else'});

    expect({asked, sent: h.sent}).toEqual({
      asked: [{userId: 'u1', options: {limit: 3, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's9',
              createdAt: '2026-02-02T00:00:00.000Z',
              updatedAt: '2026-02-02T00:01:00.000Z',
              entryCount: 2,
            },
          ],
        },
      ],
    });
  });

  it('answers a list_sessions while a turn holds the lock: the list lands before that turn ends', async () => {
    const asked: Array<string | number> = [];
    const store = {
      listFor: (userId: string | number) => {
        asked.push(userId);
        return [];
      },
    } as unknown as SessionStore;
